#include <bits/stdc++.h>
#define ll long long
using namespace std;

void solve() {
    ll a = 0, b, c, d, pos = 1, bit_b, bit_c, bit_d, mask = 1;
    cin >> b >> c >> d;
    for (ll i = 0; i < 62; i++) {
        if (b&mask) bit_b = 1;
        else bit_b = 0;
        if (c&mask) bit_c = 1;
        else bit_c = 0;
        if (d&mask) bit_d = 1;
        else bit_d = 0;
        if ((bit_b && (!bit_c) && (!bit_d)) || ((!bit_b) && bit_c && bit_d)) {
            pos = 0;
            break;
        }
        if (bit_b && bit_c) {
            a += (1ll-bit_d)*mask;
        } else {
            a += bit_d*mask;
        }
        mask<<=1;
    }
    if (pos) {
        cout << a << "\n";
    } else {
        cout << -1 << "\n";
    }
}

int main() {
    ll t;
    cin >> t;
    while (t--) {
        solve();
    }
}

#include <bits/stdc++.h>
#define ll long long
using namespace std;
const ll N = 2e5+2;
const ll C = 10 + 1;

vector<ll> par(N), sz(N, 0);
vector<vector<ll>> dp(N, vector<ll> (C, 0)), ind(N, vector<ll> (C, 0)), start_cnt(N, vector<ll> (C, 0)), end_cnt(N, vector<ll> (C,0));

ll find_par(ll a) {
    if (par[a] == a) return a;
    return par[a] = find_par(par[a]);
}

void unite(ll a, ll b){
    a = find_par(a), b = find_par(b);
    if (a == b) return;
    if (sz[b] > sz[a]) swap(a, b);
    sz[a] += sz[b];
    par[b] = a;
}

void reset(ll n) {
    for (ll i = 1; i <= n; i++) {
        par[i] = i;
        sz[i] = 1;
        for (ll j = 1; j < C; j++) {
            dp[i][j] = start_cnt[i][j] = end_cnt[i][j] = 0;
            ind[i][j] = i;
        }
    }
}

void solve() {
    ll n, m, a, d, k;
    cin >> n >> m;
    reset(n);
    for (ll i = 0; i < m; i++) {
        cin >> a >> d >> k;
        start_cnt[a][d]++;
        end_cnt[a + k * d][d]++;
    }
    for (ll i = 1; i <= n; i++) {
        for (ll j = 1; j < C; j++) {
            dp[i][j] = start_cnt[i][j] - end_cnt[i][j];
            if (i-j < 1) continue;
            if (dp[i-j][j]) {
                unite(ind[i-j][j], i);
                ind[i][j] = ind[i-j][j];
                dp[i][j] += dp[i-j][j];
            }
        }
    }
    ll ans = 0;
    for (ll i = 1; i <= n; i++) {
        if (find_par(i) == i) ans++;
    }
    cout << ans << "\n";
}

int main() {
    ll t;
    cin >> t;
    while (t--) {
        solve();
    }
}

#include <bits/stdc++.h>
using namespace std;
int fast_exp(int b, int e, int mod){
	int ans = 1;
	while(e){
		if(e&1) ans = (1ll*ans*b) % mod;
		b = (1ll*b*b) % mod;
		e >>= 1;
	}
	return ans;
}
const int mod = 1e9+7;
const int bits = 11;

int inv(int n){
	return fast_exp(n,mod-2,mod);
}

const int inverse_1e4 = inv(10000);
int dp[bits][bits][2][2];
void transition(int a, int p){
	p = (1ll*p*inverse_1e4) % mod;
	int negp = (mod+1-p) % mod;
	int bin[bits];
	for(int i = 0; i < bits; i++){
		bin[i] = a&1;
		a >>= 1;
	}
	for(int i = 0; i < bits; i++){
		for(int j = 0; j < bits; j++){
			int temp[2][2];

			for(int k : {0,1}) for(int l : {0,1}) temp[k][l] = (1ll*dp[i][j][k][l]*negp + 1ll*dp[i][j][k^bin[i]][l^bin[j]]*p) % mod;

			for(int k : {0,1}) for(int l : {0,1}) dp[i][j][k][l] = temp[k][l];
		}
	}
}
int main() {
    int t;
    cin >> t;
    while(t--){
    	int n;
    	cin >> n;
    	int a[n],p[n];
    	for(int i = 0; i < n; i++) cin >> a[i];
    	for(int i = 0; i < n; i++) cin >> p[i];
    	for(int i = 0; i < bits; i++) for(int j = 0; j < bits; j++) dp[i][j][0][0] = 1;
    	for(int i = 0; i < n; i++) transition(a[i],p[i]);
    	int ans = 0;
    	for(int i = 0; i < bits; i++){
    		for(int j = 0; j < bits; j++){
    			int pw2 = (1ll<<(i+j)) % mod;
    			ans += (1ll*pw2*dp[i][j][1][1]) % mod;
    			ans %= mod;
    			for(int k : {0,1}) for(int l : {0,1}) dp[i][j][k][l] = 0;
    		}
    	}
    	cout << ans << "\n";
    }
	return 0;
}

